using System;
using Marketplace.Framework;
namespace Marketplace.Domain
{
public class Money : Value<Money>
{
private const string DefaultCurrency = "EUR";
public static Money FromDecimal(
decimal amount, string currency = DefaultCurrency) =>
new Money(amount, currency);
public static Money FromString(
string amount, string currency = DefaultCurrency) =>
new Money(decimal.Parse(amount), currency);
protected Money(decimal amount, string currencyCode = "EUR")
{
if (decimal.Round(amount, 2) != amount)
throw new ArgumentOutOfRangeException(
nameof(amount),
"Amount cannot have more than two decimals");
Amount = amount;
CurrencyCode = currencyCode;
}
Implementing the Model Chapter 5
[ 116 ]
public decimal Amount { get; }
public string CurrencyCode { get; }
public Money Add(Money summand)
{
if (CurrencyCode != summand.CurrencyCode)
throw new CurrencyMismatchException(
"Cannot sum amounts with different currencies");
return new Money(Amount + summand.Amount);
}
public Money Subtract(Money subtrahend)
{
if (CurrencyCode != subtrahend.CurrencyCode)
throw new CurrencyMismatchException(
"Cannot subtract amounts with different currencies");
return new Money(Amount - subtrahend.Amount);
}
public static Money operator +(
Money summand1, Money summand2) =>
summand1.Add(summand2);
public static Money operator -(
Money minuend, Money subtrahend) =>
minuend.Subtract(subtrahend);
}
public class CurrencyMismatchException : Exception
{
public CurrencyMismatchException(string message) :
base(message)
{
}
}
}
First, we passed currency information to the constructor and both factory methods. By
default, factories will use EUR if no currency is specified. We also keep currency
information inside the class. Second, Add and Subtract methods started to check if both
operands have the same currency. In case currencies of operands don't match, these
methods throw an exception.
Implementing the Model Chapter 5
[ 117 ]
We also added a domain-specific exception that explicitly tells us that operations on two
instances of Money cannot be completed because they have different currencies.
Imagine how many bugs such simple technique can prevent in a multicurrency system,
where developers too often forget that monetary value for the same decimal amount can be
drastically different, depending on which currency this amount of money is issued? For
example, one US Dollar is roughly equal to 110 Japanese Yen and adding 1 to 110, in this
case, won't give you the right result.
One thing that remains uncovered with our Money object is that we can supply any string
as currency code and it will be accepted. As you might imagine we can have this failure
very easily:
