Title != null
&& Text != null
&& Price?.Amount > 0,
ClassifiedAdState.Active =>
Title != null
&& Text != null
&& Price?.Amount > 0
&& ApprovedBy != null,
_ => true
});
if (!valid)
throw new InvalidEntityStateException(
this, $"Post-checks failed in state {State}");
