.Select(@event =>
new EventData(
eventId: Guid.NewGuid(),
type: @event.GetType().Name,
isJson: true,
data: Serialize(@event),
metadata: Serialize(
new EventMetadata {ClrType =
@event.GetType().AssemblyQualifiedName})
))
.ToArray();
return connection.AppendToStreamAsync(
streamName,
version,
preparedEvents);
}
private static byte[] Serialize(object data)
=> Encoding.UTF8.GetBytes(
JsonConvert.SerializeObject(data));
}
}
Since this code is copied from the EsAggregateStore class, it would make sense to use
this method there as well, and you can see the changed code in the GitHub repository.
