The next thing is, of course, our ProjectionManager. It needs to be able to work with the
checkpoint store. We don't need it to know about RavenDB since it is only needed for
projections and the checkpoint store. But it needs to call the checkpoint store when making
a subscription and to save the position after projecting each event. So, we need to add the
ICheckpointStore parameter and call the two methods that this interface has, as follows:
using System.Linq;
using System.Threading.Tasks;
using EventStore.ClientAPI;
using Marketplace.Framework;
using Serilog;
using Serilog.Events;
namespace Marketplace.Infrastructure
{
public class ProjectionManager
{
private readonly IEventStoreConnection _connection;
private readonly ICheckpointStore _checkpointStore;
private readonly IProjection[] _projections;
private EventStoreAllCatchUpSubscription _subscription;
public ProjectionManager(
IEventStoreConnection connection,
ICheckpointStore checkpointStore,
params IProjection[] projections)
{
_connection = connection;
_checkpointStore = checkpointStore;
_projections = projections;
}
public async Task Start()
{
var settings = new CatchUpSubscriptionSettings(2000, 500,
Log.IsEnabled(LogEventLevel.Verbose),
false, "try-out-subscription");
var position = await _checkpointStore.GetCheckpoint();
_subscription = _connection.SubscribeToAllFrom(position,
settings, EventAppeared);
}
public void Stop() => _subscription.Stop();
private async Task EventAppeared(
EventStoreCatchUpSubscription _,
